const $=(id)=>host.querySelector('#'+id);
const validPrice=(s)=>{s=String(s).trim();if(!/^(?:\d+)(?:\.\d{1,2})?$/.test(s))return NaN;const n=Number(s);return Number.isFinite(n)&&n>=0&&n<=1e5?Math.round(n*100):NaN};
function money(cents){const code=store==='jp'?'JPY':'USD';const nf=new Intl.NumberFormat(lang==='ja'?'ja-JP':lang==='ar'?'ar-EG':'en-US',{style:'currency',currency:code,minimumFractionDigits:2,maximumFractionDigits:2});return nf.format(cents/100)}
function translate(){host.setAttribute('lang',lang);host.setAttribute('dir',lang==='ar'?'rtl':'ltr');host.querySelectorAll('[data-bv]').forEach(el=>{let s=dict[lang][el.dataset.bv];if(s!==undefined)el.textContent=s});host.querySelectorAll('.bv-cur').forEach(e=>e.textContent=store==='jp'?'¥':'$');$('bv294-cta').href=appUrl[store];$('bv294-store').setAttribute('aria-label',dict[lang].store);$('bv294-lang').setAttribute('aria-label',dict[lang].lang)}
function refresh(){translate();const prices=[0,1,2].map(i=>validPrice($('bv294-price'+i).value));const owned=[0,1,2].map(i=>$('bv294-own'+i).checked);const priceBundle=validPrice($('bv294-bundle').value);for(let i=0;i<3;i++)$('bv294-row'+i).classList.toggle('is-owned',owned[i]);const ok=prices.every(Number.isSafeInteger)&&Number.isSafeInteger(priceBundle);const result=$('bv294-result');result.classList.toggle('bv-error',!ok);$('bv294-state').textContent=ok?'Bundlevero':'!';if(!ok){['bv294-diff','bv294-singles','bv294-bundletotal'].forEach(id=>$(id).textContent='—');$('bv294-result-title').textContent=dict[lang].error;$('bv294-result-note').textContent='';return}const single=prices.reduce((sum,p,i)=>sum+(owned[i]?0:p),0);const allOwned=owned.every(Boolean);let win,diff;if(allOwned){win='winnerNone';diff=priceBundle}else if(single<priceBundle){win='winnerSingles';diff=priceBundle-single}else if(single>priceBundle){win='winnerBundle';diff=single-priceBundle}else{win='winnerTie';diff=0}const d=dict[lang];$('bv294-diff').textContent=money(diff);$('bv294-singles').textContent=money(single);$('bv294-bundletotal').textContent=money(priceBundle);$('bv294-state').textContent=d[win];$('bv294-result-title').textContent=d[win];const msg=allOwned?d.saveNone:win==='winnerBundle'?d.saveBundle:win==='winnerSingles'?d.saveSingles:d.saveTie;$('bv294-result-note').textContent=msg.replace('{n}',money(diff));}
function sample(which){mode=which;[0,1,2].forEach(i=>{$('bv294-price'+i).value=initial.prices[i];$('bv294-own'+i).checked=i===0||(which==='two'&&i===1)});$('bv294-bundle').value=initial.bundle;host.querySelectorAll('[data-mode]').forEach(btn=>btn.setAttribute('aria-pressed',String(btn.dataset.mode===which)));refresh()}
function mount(){if(!document.body||document.getElementById(ID))return;document.body.prepend(host);$('bv294-lang').addEventListener('change',e=>{lang=e.target.value;refresh()});$('bv294-store').addEventListener('change',e=>{store=e.target.value;refresh()});$('bv294-reset').addEventListener('click',()=>sample('one'));host.querySelectorAll('[data-mode]').forEach(b=>b.addEventListener('click',()=>sample(b.dataset.mode)));for(let i=0;i<3;i++){for(const event of ['input','change']){$('bv294-price'+i).addEventListener(event,refresh);$('bv294-own'+i).addEventListener(event,refresh)}}$('bv294-bundle').addEventListener('input',refresh);sample('one')}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',mount,{once:true});else mount();
